-- 001 • Estrutura segura da Calculadora de Leads CDL NH
create extension if not exists pgcrypto;
create sequence if not exists lead_proposal_seq start 1;
create table if not exists public.lead_individual_prices(id uuid primary key default gen_random_uuid(),person text not null,product text not null,flag text not null,prices numeric[] not null check(cardinality(prices)=7),active boolean not null default true,updated_at timestamptz not null default now(),unique(person,product,flag));
create table if not exists public.lead_combo_prices(id uuid primary key default gen_random_uuid(),person text not null,level text not null,items jsonb not null default '[]'::jsonb,prices numeric[] not null check(cardinality(prices)=7),active boolean not null default true,updated_at timestamptz not null default now(),unique(person,level));
create table if not exists public.lead_combo_addon_prices(id uuid primary key default gen_random_uuid(),person text not null,name text not null,prices numeric[] not null check(cardinality(prices)=7),active boolean not null default true,updated_at timestamptz not null default now(),unique(person,name));
alter table public.lead_individual_prices enable row level security;alter table public.lead_combo_prices enable row level security;alter table public.lead_combo_addon_prices enable row level security;revoke all on public.lead_individual_prices,public.lead_combo_prices,public.lead_combo_addon_prices from anon,authenticated;
create table if not exists public.lead_proposals(id uuid primary key default gen_random_uuid(),code text unique not null default ('PROP-'||lpad(nextval('lead_proposal_seq')::text,5,'0')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references auth.users(id) on delete restrict default auth.uid(),status text not null default 'Rascunho' check(status in ('Rascunho','Gerada','Enviada','Aprovada','Perdida','Cancelada')),mode text not null check(mode in ('individual','combo')),person text not null,quantity integer not null check(quantity>0),client jsonb not null default '{}'::jsonb,selection jsonb not null,quote jsonb not null);
alter table public.lead_proposals enable row level security;drop policy if exists lead_proposals_own_read on public.lead_proposals;create policy lead_proposals_own_read on public.lead_proposals for select to authenticated using(created_by=auth.uid() or public.is_cdl_admin());drop policy if exists lead_proposals_own_insert on public.lead_proposals;create policy lead_proposals_own_insert on public.lead_proposals for insert to authenticated with check(created_by=auth.uid());drop policy if exists lead_proposals_own_update on public.lead_proposals;create policy lead_proposals_own_update on public.lead_proposals for update to authenticated using(created_by=auth.uid() or public.is_cdl_admin()) with check(created_by=auth.uid() or public.is_cdl_admin());grant select,insert,update on public.lead_proposals to authenticated;
create or replace function public.lead_band_index(p_qty integer,p_mode text) returns integer language sql immutable as $$ select case when p_mode='combo' then case when p_qty<=10000 then 1 when p_qty<=50000 then 2 when p_qty<=100000 then 3 when p_qty<=200000 then 4 when p_qty<=400000 then 5 when p_qty<=800000 then 6 else 7 end else case when p_qty<=5000 then 1 when p_qty<=10000 then 2 when p_qty<=30000 then 3 when p_qty<=50000 then 4 when p_qty<=100000 then 5 when p_qty<=300000 then 6 else 7 end end; $$;
create or replace function public.lead_band_label(p_qty integer,p_mode text) returns text language sql immutable as $$ select case when p_mode='combo' then (array['01 a 10.000','10.001 a 50.000','50.001 a 100.000','100.001 a 200.000','200.001 a 400.000','400.001 a 800.000','A partir de 800.001'])[public.lead_band_index(p_qty,p_mode)] else (array['01 a 5.000','5.001 a 10.000','10.001 a 30.000','30.001 a 50.000','50.001 a 100.000','100.001 a 300.000','Acima de 300.000'])[public.lead_band_index(p_qty,p_mode)] end; $$;
create or replace function public.calculate_lead_quote_base(p_mode text,p_person text,p_qty integer,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare b integer;u numeric:=0;c numeric:=0;m numeric:=0;s numeric:=0;rec record;out_items jsonb:='[]'::jsonb;sel jsonb;combo_level text;addon text;begin if auth.uid() is null then raise exception 'Acesso não autenticado.';end if;if not exists(select 1 from public.profiles where id=auth.uid() and active=true) then raise exception 'Usuário inativo.';end if;if p_mode not in ('individual','combo') or p_qty<=0 or p_person not in ('Pessoa Física','Pessoa Jurídica') then raise exception 'Parâmetros inválidos.';end if;b:=public.lead_band_index(p_qty,p_mode);if p_mode='individual' then for sel in select * from jsonb_array_elements(coalesce(p_selection,'[]'::jsonb)) loop select product,flag,prices[b] unit into rec from public.lead_individual_prices where active and person=p_person and product=sel->>'product' and flag=sel->>'flag';if found then u:=u+rec.unit;out_items:=out_items||jsonb_build_array(jsonb_build_object('name',rec.product||' — '||rec.flag,'unit_cost',rec.unit));end if;end loop;else combo_level:=p_selection->>'level';select level,prices[b] unit,items into rec from public.lead_combo_prices where active and person=p_person and level=combo_level;if found then u:=u+rec.unit;out_items:=out_items||jsonb_build_array(jsonb_build_object('name','Combo '||rec.level,'unit_cost',rec.unit,'details',rec.items));end if;for addon in select jsonb_array_elements_text(coalesce(p_selection->'addons','[]'::jsonb)) loop select name,prices[b] unit into rec from public.lead_combo_addon_prices where active and person=p_person and name=addon;if found then u:=u+rec.unit;out_items:=out_items||jsonb_build_array(jsonb_build_object('name','Adicional — '||rec.name,'unit_cost',rec.unit));end if;end loop;end if;c:=u*p_qty;if c>0 then m:=case when c<=2500 then 1 when p_mode='combo' and c<=15000 then .30 when p_mode='individual' and c<=30000 then .30 else .15 end;end if;s:=c*(1+m);return jsonb_build_object('mode',p_mode,'person',p_person,'quantity',p_qty,'band',public.lead_band_label(p_qty,p_mode),'unit_cost',round(u,4),'cost_total',round(c,2),'markup',m,'sale_total',round(s,2),'sale_unit',case when p_qty>0 then round(s/p_qty,4) else 0 end,'items',out_items);end;$$;
create or replace function public.calculate_lead_quote(p_mode text,p_person text,p_qty integer,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare x jsonb;commercial_items jsonb;begin x:=public.calculate_lead_quote_base(p_mode,p_person,p_qty,p_selection);select coalesce(jsonb_agg((i-'unit_cost')||jsonb_build_object('commercial_unit',round(((i->>'unit_cost')::numeric)*(1+(x->>'markup')::numeric),4))),'[]'::jsonb) into commercial_items from jsonb_array_elements(x->'items') i;return jsonb_build_object('mode',x->'mode','person',x->'person','quantity',x->'quantity','band',x->'band','sale_total',x->'sale_total','sale_unit',x->'sale_unit','items',commercial_items);end;$$;
create or replace function public.calculate_lead_quote_internal(p_mode text,p_person text,p_qty integer,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare x jsonb;begin x:=public.calculate_lead_quote_base(p_mode,p_person,p_qty,p_selection);return x||jsonb_build_object('policy_note','Política comercial: contratação mínima de R$ 500. Este valor é apenas um lembrete e não interfere no cálculo.');end;$$;
revoke all on function public.calculate_lead_quote_base(text,text,integer,jsonb) from public;revoke all on function public.calculate_lead_quote(text,text,integer,jsonb) from public;revoke all on function public.calculate_lead_quote_internal(text,text,integer,jsonb) from public;grant execute on function public.calculate_lead_quote(text,text,integer,jsonb) to authenticated;grant execute on function public.calculate_lead_quote_internal(text,text,integer,jsonb) to authenticated;
